parameters.jsCode:
const items = $input.all();
const reformattedItems = [];

for (const item of items) {
  // Extract raw string output from the node payload
  let rawText = item.json.output || (item.json.choices && item.json.choices[0].message.content) || item.json;

  if (typeof rawText === 'object') {
    rawText = JSON.stringify(rawText);
  }

  // Clean markdown code blocks if the LLM wrapped it in ```json ... ```
  let cleanJsonString = String(rawText)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    const parsedData = JSON.parse(cleanJsonString);

    if (parsedData.questions && Array.isArray(parsedData.questions)) {
      for (const q of parsedData.questions) {
        reformattedItems.push({
          json: {
            task_statement_id: parsedData.task_statement_id || "1.1",
            angle: q.angle || "Scenario",
            question: q.question,
            option_A: q.option_A,
            option_B: q.option_B,
            option_C: q.option_C,
            option_D: q.option_D,
            correct_answer: q.correct_answer,
            explanation: q.explanation
          }
        });
      }
    }
  } catch (err) {
    // Catch JSON parsing errors caused by truncation
    reformattedItems.push({
      json: {
        error: "JSON Truncated or Malformed",
        errorMessage: err.message,
        rawText: cleanJsonString
      }
    });
  }
}

return reformattedItems;

